function icon_svg_html($name) {
    global $ICON_LIBRARY;
    if (!isset($ICON_LIBRARY[$name])) return '';
    return '<svg class="oi" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' . $ICON_LIBRARY[$name] . '</svg>';
}

/**
 * Turn a picker value into the HTML that goes inside the icon box.
 *   lib:rocket        built-in icon
 *   text:★ or text:01 any character, number or emoji
 *   img:uploads/x.png uploaded image
 *   none              hide the icon
 * Returns null for "keep" / unknown values, meaning: leave the icon alone.
 */
function icon_value_to_html($value) {
    if (strncmp($value, 'lib:', 4) === 0) {
        $svg = icon_svg_html(substr($value, 4));
        return $svg !== '' ? $svg : null;
    }
    if (strncmp($value, 'text:', 5) === 0) {
        $t = trim(substr($value, 5));
        return $t === '' ? null : htmlspecialchars(mb_substr($t, 0, 8), ENT_QUOTES, 'UTF-8');
    }
    if (strncmp($value, 'img:', 4) === 0) {
        $p = ltrim(substr($value, 4), '/');
        // Only allow files from the uploads folder.
        if (preg_match('#^uploads/[A-Za-z0-9._-]+\.(jpe?g|png|gif|webp|svg)$#i', $p)) {
            return '<img src="' . htmlspecialchars($p, ENT_QUOTES) . '" alt="" loading="lazy">';
        }
        return null;
    }
    if ($value === 'none') return '';
    return null;
}
